import contextlib,io,json
from pathlib import Path
stream=io.StringIO()
with contextlib.redirect_stdout(stream):exec(compile(Path('/tmp/monitor_p3b5_v58.py').read_text(),'/tmp/monitor_p3b5_v58.py','exec'), {})
for line in stream.getvalue().splitlines():
    r=json.loads(line)
    if 'pool' in r:
        done=r['done']
        print(json.dumps(dict(pool=r['pool'],done=len(done),last_completed=done[-1] if done else None,active=r['active'],finished=bool(r['finished']))))
    elif 'fixed_pool' in r:
        print(json.dumps(dict(fixed_pool=r['fixed_pool'],done=len(r['rows']),last_completed=r['rows'][-1] if r['rows'] else None)))
    else:print(line)

